'use client';
import { useRef, useState, type CSSProperties, type FormEvent } from 'react';
import { Brand, type BrandName } from '../lib/brands';
import { cx } from '../lib/cx';
import { useControllable, useIsoLayoutEffect, useReducedMotion } from '../lib/hooks';
import { Icon, type IconName } from '../lib/icons';
import { avatarInk, enter, Fold, Seg, Spin, Swap, Tip, useGrow } from '../lib/motion';
import { usePopover } from '../lib/popover';
import '../designme.css';
import './scheduled-runs.css';

/** How its last run went. running while it runs now; never before its first run */
export type ScheduledRunResult = 'passed' | 'failed' | 'running' | 'never';

/** A task the agent runs on a schedule */
export interface ScheduledRun {
  key: string;
  /** Like "Weekly design QA" */
  name: string;
  /** The schedule in words, like "Mondays at 9:00" */
  schedule: string;
  /** When it runs next, like "Next in 2 days". A paused run says "Paused" instead */
  next?: string;
  /** On or paused. Defaults to on */
  enabled?: boolean;
  result?: ScheduledRunResult;
  /** When the last run ended, like "5 days ago", shown as "Passed 5 days ago" */
  ago?: string;
  /** Why the last run failed, like "Figma token expired" */
  error?: string;
  /** The label of a button that fixes a failed run, like "Reconnect Figma". It calls `onFix` */
  fix?: string;
  /** The fix is under way: its button spins */
  fixing?: boolean;
  /** A service's own logo, on a white tile. Wins over `icon` */
  brand?: BrandName;
  /** An icon on a vivid tile of `color`. Defaults to a clock */
  icon?: IconName;
  /** The tile's colour, like 'var(--dm-av-l)'. The icon on it is white, or the colour's own ink for an avatar colour */
  color?: string;
}

/** What New schedule hands over: the task, and the days it runs on, 0 for Monday to 6 for Sunday */
export interface ScheduledRunsNew {
  task: string;
  repeat: 'day' | 'monday' | 'custom';
  days: number[];
  /** The schedule in words, like "Mon, Wed, Fri at 9:00" */
  schedule: string;
  /** When it first runs, from now, like "Next in 18h" */
  next: string;
}

export interface ScheduledRunsProps {
  runs?: ScheduledRun[];
  defaultRuns?: ScheduledRun[];
  /** Called when a switch pauses or resumes a run, with the whole list */
  onRunsChange?: (runs: ScheduledRun[]) => void;
  /** Adds Run now to each row. Set the run's result to 'running' while it runs */
  onRunNow?: (key: string) => void;
  /** Called by the fix button of a failed run */
  onFix?: (key: string) => void;
  /** Adds New schedule: a task, Every day, Every Monday or Custom days, and Create */
  onCreate?: (run: ScheduledRunsNew) => void;
  /** The time new schedules run at, in words. Defaults to "9:00" */
  time?: string;
  /** The hour of that time, so the form can say when the first run is. Defaults to 9 */
  hour?: number;
  /** Defaults to "Scheduled runs" */
  title?: string;
  /** A line under the title, like "Next run in 17h". Left out, the head is the title alone: the rows already say which runs
      are on, paused or failed */
  status?: string;
  className?: string;
}

const DAY = ['Mon', 'Tue', 'Wed', 'Thu', 'Fri', 'Sat', 'Sun'];
const FULL = ['Monday', 'Tuesday', 'Wednesday', 'Thursday', 'Friday', 'Saturday', 'Sunday'];
const words = (ds: number[], time: string) => ds.length === 7 ? `Every day at ${time}` : ds.join() === '0,1,2,3,4' ? `Weekdays at ${time}`
  : ds.length === 1 ? `${FULL[ds[0]]}s at ${time}` : `${ds.map(d => DAY[d]).join(', ')} at ${time}`;
/** When the first run is, from now: in hours when it's within a day, otherwise in days */
function firstRun(ds: number[], hour: number) {
  const now = new Date(), today = (now.getDay() + 6) % 7;
  const at = ds.map(d => { const t = new Date(now); t.setDate(now.getDate() + ((d - today + 7) % 7)); t.setHours(hour, 0, 0, 0); if (t <= now) t.setDate(t.getDate() + 7); return t; })
    .sort((a, b) => +a - +b)[0];
  const h = Math.round((+at - +now) / 36e5);
  if (h < 24) return `First run in ${Math.max(1, h)}h`;
  const days = Math.round((new Date(at).setHours(0, 0, 0, 0) - new Date(now).setHours(0, 0, 0, 0)) / 864e5);
  return `First run in ${days} days`;
}

/** The fix: as wide as its words, easing to "Reconnecting" with its spinner and back */
function Fix({ label, fixing, onClick }: { label: string; fixing?: boolean; onClick: () => void }) {
  const ref = useRef<HTMLButtonElement>(null), was = useRef(0), reduce = useReducedMotion();
  useIsoLayoutEffect(() => {
    const b = ref.current; if (!b) return;
    const w1 = b.getBoundingClientRect().width, w0 = was.current; was.current = w1;
    const cs = getComputedStyle(b), t = cs.getPropertyValue('--dm-t').trim();
    if (w0 && !reduce && Math.abs(w1 - w0) > .5) b.animate([{ width: w0 + 'px' }, { width: w1 + 'px' }], { duration: (t.endsWith('ms') ? parseFloat(t) : parseFloat(t) * 1000) || 340, easing: cs.getPropertyValue('--dm-ease').trim() || 'ease' });
  }, [fixing]);
  return <button ref={ref} type="button" className="dm-pill dm-accent dm-sm" aria-disabled={fixing || undefined} onClick={() => !fixing && onClick()}>{fixing ? <><Spin />Reconnecting</> : label}</button>;
}

/** Recurring agent tasks: each with its schedule in words, when it runs next, how its last run went, Run now and an
    on/off switch. A paused one dims and says so; a failed one says why and can offer a fix; New schedule makes another. */
export function ScheduledRuns({ runs, defaultRuns = [], onRunsChange, onRunNow, onFix, onCreate, time = '9:00', hour = 9, title = 'Scheduled runs', status, className }: ScheduledRunsProps) {
  const [list, setList] = useControllable(runs, defaultRuns, onRunsChange);
  // the card grows with its rows, and eases as a fix folds open or shut (as grow() on the site)
  const [root, inner] = useGrow();
  const field = useRef<HTMLInputElement>(null);
  // the form opens under its button, or above it when there is no room
  const menu = usePopover();
  const [task, setTask] = useState('');
  const [repeat, setRepeat] = useState<ScheduledRunsNew['repeat']>('day');
  const [custom, setCustom] = useState([0, 2, 4]);
  const days = repeat === 'day' ? [0, 1, 2, 3, 4, 5, 6] : repeat === 'monday' ? [0] : custom;
  // a form that opened above New schedule grows upwards when Custom adds the days, so it is held by its bottom edge
  const [bottom, setBottom] = useState<CSSProperties>({});
  const up = String((menu.pop.style as Record<string, unknown>)['--dm-origin'] ?? '').startsWith('bottom');
  useIsoLayoutEffect(() => {
    const r = root.current?.querySelector<HTMLElement>('.dm-shx-add')?.getBoundingClientRect(), h = root.current?.getBoundingClientRect();
    setBottom(menu.open && up && r && h ? { top: 'auto', bottom: h.bottom - r.top + 6 } : {});
  }, [menu.open, repeat, up]);
  const [first] = useState(() => list.map(r => r.key));

  const on = (r: ScheduledRun) => r.enabled !== false;
  const toggle = (key: string) => setList(list.map(r => r.key === key ? { ...r, enabled: !on(r) } : r));
  const create = (e: FormEvent) => {
    e.preventDefault(); if (!task.trim() || !days.length) return;
    onCreate?.({ task: task.trim(), repeat, days, schedule: words(days, time), next: firstRun(days, hour).replace('First run', 'Next') });
    menu.close(); setTask('');
  };

  return (
    <div data-dm="" ref={root} className={cx('dm-shx dm-panel dm-growing', className)}>
      <div ref={inner} className="dm-grow">
      <div className="dm-shx-h"><span className="dm-shx-hi" aria-hidden="true"><Icon name="clock" size="xs" /></span><div><b>{title}</b>{status && <Swap className="dm-muted dm-shx-st">{status}</Swap>}</div></div>
      <div className="dm-shx-list" role="list" aria-label="Schedules">
        {list.map(r => {
          const at = first.indexOf(r.key), motion = enter(at >= 0 ? at * 50 : 0), running = r.result === 'running';
          const res = running ? 'Running now' : r.result === 'passed' ? 'Passed' + (r.ago ? ' ' + r.ago : '') : r.result === 'failed' ? 'Failed' + (r.error ? ': ' + r.error : '') : 'No runs yet';
          const st = running ? 'run' : r.result === 'passed' ? 'ok' : r.result === 'failed' ? 'bad' : 'none';
          const color = r.color ?? 'var(--dm-av-b)';
          return (
            <div key={r.key} className={cx('dm-shx-r', motion.className, !on(r) && 'dm-off')} style={motion.style} role="listitem" data-st={st}>
              {r.brand
                ? <span className="dm-ic dm-brandic" aria-hidden="true"><Brand name={r.brand} /></span>
                : <span className="dm-ic" style={{ background: color, color: avatarInk(color) ?? '#fff' }} aria-hidden="true"><Icon name={r.icon ?? 'clock'} size="xs" /></span>}
              <span className="dm-t">
                <span className="dm-nm">{r.name}</span>
                <Swap className="dm-d">{r.schedule + ' · ' + (on(r) ? r.next ?? '' : 'Paused')}</Swap>
                <span className="dm-res">{running ? <Spin /> : (r.result === 'passed' || r.result === 'failed') && <Icon name={r.result === 'passed' ? 'ok' : 'alert'} size="xs" />}<Swap className={running ? 'dm-shim' : undefined}>{res}</Swap></span>
              </span>
              <span className="dm-shx-act">
                {onRunNow && <Tip label="Run now"><button type="button" className="dm-ib dm-shx-run" aria-label={`Run ${r.name} now`} disabled={running || !on(r)} onClick={() => onRunNow(r.key)}><Icon name="play" /></button></Tip>}
                <Tip label={on(r) ? 'Pause' : 'Resume'}><button type="button" className="dm-toggle" role="switch" aria-checked={on(r)} aria-label={r.name} onClick={() => toggle(r.key)} /></Tip>
              </span>
              <Fold open={r.result === 'failed' && !!r.fix} className="dm-shx-fx">
                <div><Fix label={r.fix ?? ''} fixing={r.fixing} onClick={() => onFix?.(r.key)} /></div>
              </Fold>
            </div>
          );
        })}
      </div>
      {onCreate && <>
        <div className="dm-shx-ft"><button type="button" className="dm-shx-add" {...menu.trigger} aria-haspopup="dialog" onClick={() => { menu.trigger.onClick(); if (!menu.open) requestAnimationFrame(() => field.current?.focus({ preventScroll: true })); }}><Icon name="plus" size="xs" />New schedule</button></div>
        <div {...menu.pop} style={{ ...menu.pop.style, ...bottom }} className={cx(menu.pop.className, 'dm-shx-pop')} role="dialog" aria-label="New schedule">
          <form className="dm-shx-f" onSubmit={create}>
            <h4>New schedule</h4>
            <input ref={field} className="dm-shx-in" value={task} onChange={e => setTask(e.target.value)} placeholder="What should the agent do?" aria-label="What should the agent do?" spellCheck={false} autoComplete="off" />
            <Seg className="dm-shx-rep" label="Repeat" value={repeat} onChange={setRepeat} options={[{ value: 'day', label: 'Every day' }, { value: 'monday', label: 'Every Monday' }, { value: 'custom', label: 'Custom' }]} />
            {repeat === 'custom' && (
              <div className="dm-shx-days" role="group" aria-label="Days">
                {DAY.map((d, i) => <button type="button" key={d} aria-pressed={custom.includes(i)} aria-label={FULL[i]} onClick={() => setCustom(c => c.includes(i) ? c.filter(x => x !== i) : [...c, i].sort())}>{d[0]}</button>)}
              </div>
            )}
            <div className="dm-shx-ff"><span className="dm-muted dm-shx-sum">{days.length ? firstRun(days, hour) : 'Pick at least one day'}</span><button type="submit" className="dm-pill dm-accent dm-sm" disabled={!task.trim() || !days.length}>Create</button></div>
          </form>
        </div>
      </>}
      </div>
    </div>
  );
}

/* Generated from designme.dev by scripts/sync.mjs. Edit the site, then sync. */
/* ---------- Scheduled runs ---------- */
/* recurring agent tasks: the schedule in words, when it runs next and how its last run went, with Run now and an on/off
   switch. The card sits on two columns (owner, 18 Nov), its content 16px from every edge: the head's neutral mark in a 28px
   column with each run's mark under it, and the title and each run's words 12px after it; each run's mark, its three lines
   and its controls share one centre line, and the switches end on the content's right edge. A row is not a button, so it has
   no hover fill. The last line is the result, led by its mark (beside it, never over the run's own): a green tick when it
   passed, a red sign and the reason when it failed, with the fix under it, and a turning ring with words that shimmer while it
   runs. A paused one dims and says so. A run's mark is its tool's logo on a white tile, or its icon on a vivid tile of its
   colour (white or the colour's own ink on it). The card grows and shrinks with its rows (grow()) */
.dm-shx{padding:var(--dm-s-4);display:flex;flex-direction:column}
.dm-shx.dm-growing:has(.dm-pop.dm-open){overflow:visible}
.dm-shx-h{display:flex;align-items:center;gap:var(--dm-s-3);padding-bottom:var(--dm-s-2)}
.dm-shx-hi{width:28px;height:28px;display:grid;place-items:center;flex:none;border-radius:calc(8px * var(--dm-rk-m,var(--dm-rk)));color:var(--dm-fg2);background:var(--dm-chip)}
.dm-shx-h>div{flex:1;display:flex;flex-direction:column;min-width:0}
.dm-shx-h b{font-weight:500;font-size:14px;line-height:20px}
.dm-shx-st{font-size:12px;line-height:18px;white-space:nowrap;overflow:hidden;text-overflow:ellipsis}
.dm-shx-list{display:flex;flex-direction:column}
.dm-shx-r{display:grid;grid-template-columns:28px minmax(0,1fr) auto;align-items:center;column-gap:var(--dm-s-3);padding:var(--dm-s-2) 0;font-size:13px}
.dm-shx-r .dm-ic{width:28px;height:28px;border-radius:calc(8px * var(--dm-rk-m,var(--dm-rk)));display:grid;place-items:center;grid-row:1/4;align-self:center;transition:opacity var(--dm-t-fast) var(--dm-ease)}
.dm-shx-r .dm-ic.dm-brandic{background:var(--dm-surface);box-shadow:inset 0 0 0 1px color-mix(in srgb,var(--dm-line) 50%,transparent);color:var(--dm-fg)}
.dm-shx-r .dm-ic .dm-brand{width:15px;height:15px}
/* the name, the schedule and the result take the words' column; Run now and the switch sit beside all three */
.dm-shx-r .dm-t{display:contents}
.dm-shx-r :is(.dm-nm,.dm-d,.dm-res){grid-column:2;transition:color var(--dm-t-fast) var(--dm-ease)}
.dm-shx-r .dm-nm{line-height:20px}
/* a paused one dims: its tile fades, and its name and result step down to muted, so the text stays readable */
.dm-shx-r.dm-off .dm-ic{opacity:.5}.dm-shx-r.dm-off :is(.dm-nm,.dm-res .dm-i){color:var(--dm-muted)}
.dm-shx-r .dm-nm,.dm-shx-r .dm-d{min-width:0;white-space:nowrap;overflow:hidden;text-overflow:ellipsis}
.dm-shx-r .dm-d{font-size:12px;line-height:18px;color:var(--dm-muted)}
.dm-shx-r .dm-res{display:flex;align-items:center;gap:5px;min-width:0;height:18px;font-size:12px;color:var(--dm-muted)}
.dm-shx-r .dm-res>span{min-width:0;white-space:nowrap;overflow:hidden;text-overflow:ellipsis}
.dm-shx-r .dm-res .dm-shim{font-size:inherit}
.dm-shx-r .dm-res .dm-i{flex:none;color:var(--dm-ok-mark)}
.dm-shx-r .dm-res .dm-spin{width:11px;height:11px;margin:0 .5px;color:var(--dm-accent-mark,var(--dm-accent))}
.dm-shx-r[data-st="bad"] .dm-res{color:var(--dm-bad)}
/* why it failed is never cut short: on a narrow card it wraps, its sign on the first line */
.dm-shx-r[data-st="bad"] .dm-res{height:auto;min-height:18px;align-items:flex-start;line-height:18px}
.dm-shx-r[data-st="bad"] .dm-res .dm-i{margin-top:3px}
.dm-shx-r[data-st="bad"] .dm-res>span{white-space:normal;text-wrap:pretty}
.dm-shx-r[data-st="bad"] .dm-res .dm-i{color:var(--dm-bad-mark)}
.dm-shx-act{grid-column:3;grid-row:1/4;align-self:center;display:flex;align-items:center;gap:var(--dm-s-2)}
.dm-shx-run{width:28px;height:28px}
.dm-shx-run:disabled{opacity:1;cursor:not-allowed;background:none;color:var(--dm-dis);transform:none}
.dm-shx-r .dm-shx-fx{grid-column:2/-1;grid-row:4}
.dm-shx-fx>div{overflow-clip-margin:0px}
.dm-shx-fx>div>div{display:flex;flex-wrap:wrap;gap:6px;padding-top:var(--dm-s-2)}
.dm-shx-fx .dm-pill .dm-spin{width:11px;height:11px}
/* New schedule: its + centred in the marks' column and its words on the title's; the hover box starts on the content's edge */
.dm-shx-add{display:flex;align-items:center;gap:var(--dm-s-3);align-self:flex-start;height:32px;margin-top:var(--dm-s-1);padding:0 var(--dm-s-3) 0 0;font-size:13px;color:var(--dm-fg2);border-radius:calc(8px * var(--dm-rk-m,var(--dm-rk)));transition:background-color var(--dm-t-fast) var(--dm-ease),color var(--dm-t-fast) var(--dm-ease)}
.dm-shx-add>.dm-i{width:28px;padding:0 8px;box-sizing:border-box}
.dm-shx-add[aria-expanded="true"]{color:var(--dm-fg);background:var(--dm-row)}
@media (hover:hover) and (pointer:fine){.dm-shx-add:hover{color:var(--dm-fg);background:var(--dm-row)}}
.dm-shx-pop{width:272px;padding:var(--dm-s-3)}
.dm-shx-f{display:flex;flex-direction:column;gap:var(--dm-s-2)}
.dm-shx-f h4{margin:0 0 2px;font-size:13px;font-weight:500}
.dm-shx-in{width:100%;height:32px;border:0;outline:0;border-radius:var(--dm-r-field);background:var(--dm-surface);box-shadow:inset 0 0 0 1px color-mix(in srgb,var(--dm-field-line) 50%,transparent);padding:0 10px;font:inherit;font-size:13px;color:var(--dm-fg);transition:box-shadow var(--dm-t-fast)}
@supports (corner-shape:squircle){.dm-shx-in{corner-shape:squircle;border-radius:var(--dm-r-field-sq)}}
.dm-shx-in::placeholder{color:var(--dm-muted)}
.dm-shx-in:focus{box-shadow:inset 0 0 0 1px color-mix(in srgb,var(--dm-field-line-strong) 50%,transparent)}
.dm-shx-rep{display:flex}
.dm-shx-rep button{flex:1 1 auto;padding:0 var(--dm-s-2);white-space:nowrap}
.dm-shx-days{display:grid;grid-template-columns:repeat(7,minmax(0,1fr));gap:var(--dm-s-1)}
.dm-shx-days button{height:28px;border-radius:var(--dm-r-sm);background:var(--dm-chip);font-size:12px;color:var(--dm-fg2);transition:background-color var(--dm-t-fast) var(--dm-ease),color var(--dm-t-fast) var(--dm-ease)}
@media (hover:hover) and (pointer:fine){.dm-shx-days button:hover{background:var(--dm-hover);color:var(--dm-fg)}}
.dm-shx-days button[aria-pressed="true"]{background:var(--dm-accent-bg);color:var(--dm-accent-fg,var(--dm-accent))}
.dm-shx-ff{display:flex;align-items:center;gap:var(--dm-s-2);padding-top:2px}
.dm-shx-sum{flex:1;min-width:0;font-size:12px;white-space:nowrap;overflow:hidden;text-overflow:ellipsis}
/* nothing in it grows or shrinks when it is pressed (owner, 18 Nov); Clean's ink primary alone presses */
.dm-shx :is(.dm-ib,.dm-pill,.dm-shx-days button):active,:root[data-style="clean"] .dm-shx .dm-ib:active,:root [data-style="clean"] .dm-shx .dm-ib:active,:root [data-style="clean"].dm-shx .dm-ib:active{transform:none}
/* Clean (owner, 17 and 18 Nov): the head an off-white strip with a hairline under it; the runs' marks one neutral grey with
   a hairline (their logos keep their own colours); New schedule a flat secondary button on an off-white foot strip, 8px from
   the card's edges; the content 16px in from each edge and 16px from each strip; the form's days are round chips, its fields
   10px corners, and it scales and fades from its button with the card's corners */
:root[data-style="clean"] .dm-shx.dm-panel,:root [data-style="clean"] .dm-shx.dm-panel,:root [data-style="clean"].dm-shx.dm-panel{padding:0}
:root[data-style="clean"] .dm-shx-h,:root [data-style="clean"] .dm-shx-h,:root [data-style="clean"].dm-shx-h{min-height:calc(28px + 2 * var(--dm-strip-y) + 1px);padding:var(--dm-strip-y) 16px;background:var(--dm-strip);border-bottom:1px solid var(--dm-line);border-radius:var(--dm-r-card) var(--dm-r-card) 0 0}
:root[data-style="clean"] .dm-shx-hi,:root [data-style="clean"] .dm-shx-hi,:root [data-style="clean"].dm-shx-hi{background:var(--dm-surface);box-shadow:inset 0 0 0 1px var(--dm-hair);border-radius:10px}
:root[data-style="clean"] .dm-shx-list,:root [data-style="clean"] .dm-shx-list,:root [data-style="clean"].dm-shx-list{padding:var(--dm-s-2) var(--dm-s-4)}
:root[data-style="clean"] .dm-shx-r .dm-ic,:root [data-style="clean"] .dm-shx-r .dm-ic,:root [data-style="clean"].dm-shx-r .dm-ic,:root[data-style="clean"] .dm-shx-r .dm-ic.dm-brandic,:root [data-style="clean"] .dm-shx-r .dm-ic.dm-brandic,:root [data-style="clean"].dm-shx-r .dm-ic.dm-brandic{background:var(--dm-surface)!important;color:var(--dm-fg2)!important;box-shadow:inset 0 0 0 1px var(--dm-hair);border-radius:10px}
:root[data-style="clean"] .dm-shx-r .dm-res .dm-i,:root [data-style="clean"] .dm-shx-r .dm-res .dm-i,:root [data-style="clean"].dm-shx-r .dm-res .dm-i{color:color-mix(in srgb,var(--dm-ok-mark) 80%,var(--dm-ok))}
:root[data-style="clean"] .dm-shx-r[data-st="bad"] .dm-res .dm-i,:root [data-style="clean"] .dm-shx-r[data-st="bad"] .dm-res .dm-i,:root [data-style="clean"].dm-shx-r[data-st="bad"] .dm-res .dm-i{color:var(--dm-bad-mark)}
:root[data-style="clean"] .dm-shx-r.dm-off .dm-res .dm-i,:root [data-style="clean"] .dm-shx-r.dm-off .dm-res .dm-i,:root [data-style="clean"].dm-shx-r.dm-off .dm-res .dm-i{color:var(--dm-muted)}
